import { ArrowRight } from 'lucide-react'

import { Button } from '../../components/ui/button'
import { Section, SectionHeading, type HeadingLevel } from '../../components/ui/section'
import { cn } from '../../lib/utils'

export type HeroAction = {
  label: string
  href?: string
  variant?: 'default' | 'outline' | 'secondary' | 'ghost'
}

export type Hero01Props = {
  /**
   * Optional label above the headline. Intentionally has no default: an earlier
   * version shipped a hardcoded "Now in open beta" pill, which meant every
   * consumer who installed this block inherited a status badge making a claim
   * about their product. Pass one if you mean it.
   */
  eyebrow?: string
  title: string
  description?: string
  actions?: HeroAction[]
  /**
   * Whether the copy is centered in the band or set flush to the left edge of
   * the container.
   *
   * This is the hero's own alignment and not `SectionHeading`'s, because the two
   * are not the same decision: a left-aligned hero is nearly always the left half
   * of a two-column band with a panel or an instrument beside it, and that column
   * is narrower than the container, so the alignment has to be the hero's before
   * the container can be anything. Three of the four NaniSoft sites compose a
   * left-aligned hero, each beside a panel, and each wrote the alignment by hand
   * because this Block was the centered form only.
   *
   * It has no visual effect on its own, which is the point: it aligns the copy
   * inside whatever width it is given.
   *
   * @defaultValue 'center'
   */
  align?: 'center' | 'left'
  /**
   * Heading level for the title. Defaults to `h2` because a block is composed,
   * not a page: it installs into a consumer's layout and renders
   * inside catalog previews, so the surrounding document already owns the `h1`.
   * A page that uses this block as its top-level heading opts in with
   * `headingLevel="h1"`; a document that already names this section in its own
   * heading passes one level deeper. See `HeadingLevel`.
   */
  headingLevel?: HeadingLevel
}

/**
 * A centered marketing hero with an optional eyebrow, a headline, a supporting
 * line and up to two actions.
 *
 * The copy and the actions are props, and the Block ships none of either. It
 * previously shipped nothing of its own here and the remaining thing worth saying
 * is the alignment: `align` is this Block's own prop rather than a pass-through of
 * `SectionHeading`'s, because a left-aligned hero is nearly always one column of a
 * two-column band and that column is narrower than the container, so the alignment
 * has to be decided before the container is anything.
 */
export function Hero01({
  eyebrow,
  title,
  description,
  actions = [],
  align = 'center',
  headingLevel = 'h2',
}: Hero01Props) {
  return (
    <Section className="relative overflow-hidden">
      <div
        aria-hidden
        className="from-primary/5 pointer-events-none absolute inset-0 -z-10 bg-gradient-to-b to-transparent"
      />
      <div
        data-slot="hero-01-copy"
        className={cn(
          'flex flex-col gap-10',
          align === 'center' ? 'items-center text-center' : 'items-start text-left',
        )}
      >
        {eyebrow ? (
          <span className="bg-muted text-muted-foreground rounded-full px-3 py-1 text-xs font-medium">
            {eyebrow}
          </span>
        ) : null}

        <SectionHeading
          as={headingLevel}
          align={align}
          title={title}
          description={description}
        />

        {actions.length ? (
          <div className="flex flex-col gap-3 sm:flex-row">
            {actions.map((action, index) => (
              // Positional, for the same reason as `pricing-01`'s feature list:
              // the label is display content, and two actions may share one.
              // Safe here because the list is static and never reordered.
              <Button
                key={index}
                size="lg"
                variant={action.variant ?? (index === 0 ? 'default' : 'outline')}
                className="group"
              >
                {action.label}
                {index === 0 ? (
                  <ArrowRight className="motion-safe:transition-transform size-4 group-hover:translate-x-0.5" />
                ) : null}
              </Button>
            ))}
          </div>
        ) : null}
      </div>
    </Section>
  )
}

export default Hero01

import type { ReactNode } from 'react'
import { cn } from '../../lib/utils'

/**
 * Container primitive. Every block composes its own section from this so vertical
 * rhythm stays consistent across the catalog instead of being re-invented per block.
 */
export function Section({
  className,
  children,
  ...props
}: React.ComponentProps<'section'>) {
  return (
    <section
      className={cn('py-16 sm:py-24', className)}
      {...props}
    >
      <div className="mx-auto w-full max-w-6xl px-6 lg:px-8">
        {children}
      </div>
    </section>
  )
}

/**
 * The six heading levels a block can be composed at.
 *
 * Every block takes a `headingLevel` prop typed with this and forwards it to the
 * one heading it renders, so the surrounding document decides where the block
 * sits in the outline rather than the block deciding for itself. `h2` is the
 * default because a block is composed, not a page.
 *
 * A block rendered where the document *already* owns a heading for the same
 * content passes one level deeper. A catalog card already names the block in its
 * own `h2`, so the copy of the block embedded inside that card passes `h3`: the
 * embedded heading then reads as a child of the card that introduces it instead
 * of as a second, competing sibling. This is a fact about where the block was
 * placed, not about the block, which is why it is a prop and not a default.
 */
export type HeadingLevel = 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'

/**
 * The heading a section opens with: an optional eyebrow, the title, an optional
 * supporting line, and the level of the one heading it renders.
 *
 * `align` is the block's own decision about where the heading sits in the
 * container. `center` is right for a band that is only a heading, and `left` is
 * right for a section with content under it, where a centred title above a
 * left-aligned list reads as two unrelated pieces.
 */
export function SectionHeading({
  index,
  eyebrow,
  title,
  as: Heading = 'h2',
  description,
  align = 'center',
  className,
}: {
  /**
   * A short ordinal for the section: "01", "02", "7". It is rendered in the mono
   * face above the title, because a section's position in a sequence is machine
   * notation rather than a word, and the mono stack is what this repository
   * annotates machine-readable values with.
   *
   * It is a separate prop from `eyebrow` and not a default value of it, because
   * the two say different things: an eyebrow is a word a reader reads, and an
   * index is a number that is only meaningful beside the section it counts. All
   * four NaniSoft sites render one of these above every section heading, and
   * three of them render it beside a label rather than above a title, which is
   * the same fact in a different arrangement.
   */
  index?: string
  eyebrow?: ReactNode
  title: ReactNode
  description?: ReactNode
  align?: 'center' | 'left'
  /**
   * Heading level. Defaults to `h2` because blocks compose under a page heading.
   * A page that renders a block as its primary heading passes `as="h1"`; a
   * document with no `h1` gives screen-reader and search engines no top-level
   * entry point.
   */
  as?: HeadingLevel
  className?: string
}) {
  return (
    <div
      className={cn(
        'flex flex-col gap-4',
        align === 'center' ? 'items-center text-center' : 'items-start text-left',
        className,
      )}
    >
      {index ? (
        <span className="text-muted-foreground font-mono text-xs font-normal tracking-normal">
          {index}
        </span>
      ) : null}
      {eyebrow ? (
        <span className="text-muted-foreground text-sm font-medium tracking-wide uppercase">
          {eyebrow}
        </span>
      ) : null}
      <Heading className="text-3xl font-semibold tracking-tight text-balance sm:text-4xl">
        {title}
      </Heading>
      {description ? (
        <p className="text-muted-foreground max-w-2xl text-lg text-pretty">
          {description}
        </p>
      ) : null}
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
